let researchDataOverlay: ResearchDataDict | null = null;

export function setResearchDataOverlay(overlay: ResearchDataDict | null): void {
  researchDataOverlay = overlay && typeof overlay === 'object' ? overlay : null;
}

export function getResearchDataOverlay(): ResearchDataDict | null {
  return researchDataOverlay;
}

export function getMaxLevel(researchId: number | string): number {
  const r = researchDataOverlay?.[researchId] || researchData[researchId];
  if (!r) return 0;
  let max = 0;
  for (const k of Object.keys(r)) {
    const num = Number(k);
    if (Number.isFinite(num) && num > max) max = num;
  }
  return max;
}

export function getResearchLevelData(
  researchId: number | string,
  targetLevel: number | string
): ResearchLevelMeta | null {
  const tech = researchDataOverlay?.[researchId] || researchData[researchId];
  if (!tech) return null;
  const meta = (tech as Record<string | number, any>)[targetLevel];
  if (!meta || typeof meta !== 'object') return null;
  return meta as ResearchLevelMeta;
}

export function getMissingRequirements(
  researchId: number | string,
  targetLevel: number | string,
  currentResearchesMap: Map<number, number> | Record<number, number> | any,
  researchCenterLevel?: number
): MissingResearchRequirement[] {
  const numId = Number(researchId);
  const numLvl = Number(targetLevel);
  const maxLvl = getMaxLevel(numId);
  if (maxLvl === 0) return [{ type: 'unknownResearch', researchId: numId }];

  const getResLevel = (id: number | string): number => {
    if (currentResearchesMap?.get && typeof currentResearchesMap.get === 'function') {
      return currentResearchesMap.get(Number(id)) || 0;
    }
    return currentResearchesMap?.[id] || 0;
  };

  if (numLvl > maxLvl) {
    return [
      {
        type: 'maxLevel',
        researchId: numId,
        current: getResLevel(numId),
        max: maxLvl,
      },
    ];
  }

  const meta = getResearchLevelData(numId, numLvl);
  if (!meta) return [{ type: 'notFound', researchId: numId, level: numLvl }];

  const missing: MissingResearchRequirement[] = [];

  // 1. Previous level prerequisite
  if (numLvl > 1) {
    const curSelf = getResLevel(numId);
    if (curSelf < numLvl - 1) {
      missing.push({
        type: 'research',
        researchId: numId,
        required: numLvl - 1,
        current: curSelf,
      });
    }
  }

  // 2. Research Center level requirement
  if (meta.b) {
    const curRc = Number.isFinite(researchCenterLevel) ? (researchCenterLevel as number) : 0;
    if (curRc < meta.b) {
      missing.push({
        type: 'building',
        buildingId: 43,
        required: meta.b,
        current: curRc,
      });
    }
  }

  // 3. Other prerequisite researches
  if (Array.isArray(meta.r)) {
    for (const [reqId, reqLvl] of meta.r) {
      const curReq = getResLevel(reqId);
      if (curReq < reqLvl) {
        missing.push({
          type: 'research',
          researchId: reqId,
          required: reqLvl,
          current: curReq,
        });
      }
    }
  }

  return missing;
}

export function isAvailable(
  researchId: number | string,
  targetLevel: number | string,
  currentResearchesMap: any,
  researchCenterLevel?: number
): boolean {
  return getMissingRequirements(researchId, targetLevel, currentResearchesMap, researchCenterLevel).length === 0;
}

export function calculateEffectiveDurationMs(
  researchId: number | string,
  targetLevel: number | string,
  speedBonusMultiplier?: number
): number {
  const meta = getResearchLevelData(researchId, targetLevel);
  if (!meta || !meta.d) return 0;
  const mult =
    Number.isFinite(speedBonusMultiplier) && (speedBonusMultiplier as number) > 0 && (speedBonusMultiplier as number) <= 1
      ? (speedBonusMultiplier as number)
      : 0.892;
  return Math.round(meta.d * 1000 * mult);
}

export function getMissingCosts(
  researchId: number | string,
  targetLevel: number | string,
  currentMaterialsMap: Map<number, number> | Record<number, number> | any
): MissingResearchCost[] {
  const meta = getResearchLevelData(researchId, targetLevel);
  if (!meta || !meta.c) return [];
  const missing: MissingResearchCost[] = [];
  const getMat = (id: number): number => {
    if (currentMaterialsMap?.get && typeof currentMaterialsMap.get === 'function') {
      return currentMaterialsMap.get(id) || 0;
    }
    return currentMaterialsMap?.[id] || 0;
  };
  for (const [matIdStr, reqAmount] of Object.entries(meta.c)) {
    const matId = Number(matIdStr);
    const cur = getMat(matId);
    if (cur < reqAmount) {
      missing.push({
        materialId: matId,
        required: reqAmount,
        current: cur,
        deficit: reqAmount - cur,
      });
    }
  }
  return missing;
}

export function requiresSpecialResource(researchId: number | string, level: number = 1): boolean {
  const meta = getResearchLevelData(researchId, level) || (researchData[researchId] as any)?.['1'];
  if (!meta || !meta.c) return false;
  return Object.keys(meta.c).some((m) => Number(m) === 12 || Number(m) > 5);
}

export const researchDataHelper = {
  data: researchData,
  getMaxLevel,
  getResearchLevelData,
  getMissingRequirements,
  isAvailable,
  calculateEffectiveDurationMs,
  getMissingCosts,
  requiresSpecialResource,
};

export default researchDataHelper;
